CREATE TABLE `product` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `title` varchar(200) NOT NULL COMMENT '商品标题',
  `category` varchar(50) NOT NULL COMMENT '类目',
  `brand` varchar(50) DEFAULT NULL COMMENT '品牌',
  `price` decimal(10,2) NOT NULL COMMENT '售价(元)',
  `attrs` varchar(500) DEFAULT NULL COMMENT '核心属性, JSON字符串',
  `scene_tags` varchar(200) DEFAULT NULL COMMENT '场景标签, 逗号分隔: 夏季,员工福利,送礼...',
  `stock` int NOT NULL DEFAULT '0' COMMENT '库存',
  `points_eligible` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否可用福利积分',
  `featured` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否主推',
  `image_url` varchar(300) DEFAULT NULL COMMENT '商品图URL',
  `description` varchar(1000) DEFAULT NULL COMMENT '卖点描述(建议用LLM离线扩写以提升语义召回)',
  PRIMARY KEY (`id`),
  KEY `idx_category` (`category`),
  KEY `idx_price` (`price`)
) ENGINE=InnoDB AUTO_INCREMENT=1776 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='商品表';
